    tests = [str(v) for v in vals]
    for _ in range(8):
        tests.append(str(rng.randint(-10**9, 10**9)))
    for _ in range(6):
        tests.append(str(rng.randint(-1000, 1000)))
    for _ in range(4):
        tests.append(str(rng.randint(1, 99999) * 10**rng.randint(1, 4)))
    return tests

